          "content": "دَخَلْتَ الآنَ سِنَّ العَاشِرَةِ، وَصِرْتَ قَادِراً عَلَى الغَوْصِ خَلْفَ ظَوَاهِرِ الأَشْيَاءِ لِتَسْأَلَ عَنْ جَوْهَرِهَا الحَقِيقِيِّ. حِينَ سُئِلَ الإِمَامُ الصَّادِقُ عَلَيْهِ السَّلَامُ: «مَا العَقْلُ؟»، لَمْ يَصِفْهُ بِأَنَّهُ مُجَرَّدُ حِفْظٍ لِلمَعْلُومَاتِ أَوْ سُرْعَةٍ فِي الحِسَابِ، بَلْ وَضَعَ لَهُ تَعْرِيفاً جَامِعاً يَكْشِفُ وَظِيفَتَهُ الكُبْرَى فِي الحَيَاةِ:\n\n«العَقْلُ مَا عُبِدَ بِهِ الرَّحْمَنُ، وَاكْتُسِبَ بِهِ الجِنَانُ».\n\nشُعْلَةُ الفَهْمِ اليَوْمَ تُعَلِّمُكَ التَّفْرِقَةَ الحَاسِمَةَ بَيْنَ «العَقْلِ الأَصِيلِ» وَ«الدَّهَاءِ المَاكِرِ»: فَالآلَةُ الحَاسِبَةُ تَجْمَعُ الأَرْقَامَ بِلَا وَعْيٍ، وَالمُحْتَالُ قَدْ يَبْتَكِرُ خُطَّةً ذَكِيَّةً لِيَخْدَعَ النَّاسَ فَيَضُرَّ نَفْسَهُ وَغَيْرَهُ، وَذَلِكَ فِي مِيزَانِ الحُكَمَاءِ لَيْسَ عَقْلاً بَلْ مَكْرٌ وَضَلَالٌ! العَقْلُ الحَقِيقِيُّ جَوْهَرٌ نُورَانِيٌّ يَجْمَعُ صِفَتَيْنِ مُتَلَازِمَتَيْنِ: يَهْدِيكَ إِلَى مَعْرِفَةِ الحَقِّ وَطَاعَتِهِ، وَيَقُودُ أَفْعَالَكَ نَحْوَ الخَيْرِ وَالإِعْمَارِ؛ فَكُلُّ تَفْكِيرٍ يُثْمِرُ صِدْقاً وَنَفْعاً وَعَدْلاً هُوَ عَقْلٌ صَرِيحٌ.\n\n▪ التَّطْبِيقُ العَمَلِيُّ: افْحَصْ أَرْبَعَ خُطَطٍ فِي المِيزَانِ المِعْيَارِيِّ لِتُمَيِّزَ بَيْنَ «بَصِيرَةِ العَقْلِ البَانِي» وَ«حِيلَةِ المَكْرِ الهَدَّامِ».",
