          "content": "وَعَدَ سُرُورٌ أُخْتَهُ حُورَ أَنْ يَحْفِرَ مَعَهَا سَاقِيَةَ المَاءِ الصَّغِيرَةِ قَبْلَ الظُّهْرِ، لَكِنَّ مَازِنَ أَخْبَرَهُمَا أَنَّ تُرْبَةَ الحَدِيقَةِ صَخْرِيَّةٌ لَا يَنْفُذُ فِيهَا المَاءُ أَبَداً. فَحَصَتْ حُورُ التُّرْبَةَ بِيَدِهَا وَسَكَبَتْ قَلِيلاً مِنَ المَاءِ فَشَرِبَتْهُ الأَرْضُ بِسُهُولَةٍ، غَيْرَ أَنَّ مَازِنَ أَصَرَّ عَلَى رَأْيِهِ عِنَاداً وَرَفَضَ الِاعْتِرَافَ بِمَا رَآهُ بِعَيْنِهِ، بَيْنَمَا تَبَاطَأَ سُرُورٌ عَنِ الوَفَاءِ بِوَعْدِهِ فِي الحَفْرِ. قَالَتْ حُورُ بِهُدُوءٍ: «رَدُّ الحَقِيقَةِ الوَاضِحَةِ بَعْدَ رُؤْيَةِ دَلِيلِهَا تَكْذِيبٌ وَعِنَادٌ، وَالتَّصْدِيقُ الحَقِيقِيُّ يَا سُرُورُ هُوَ أَنْ يُوَافِقَ عَمَلُنَا قَوْلَنَا فَنَفِيَ بِوُعُودِنَا». ثُمَّ أَضَافَتْ وَهِيَ تُنَاوِلُ مَازِنَ المِجْرَفَةَ الصَّغِيرَةَ: «لَقَدْ فَطَرَ اللَّهُ قُلُوبَنَا عَلَى حُبِّ الصِّدْقِ وَالحَنِينِ إِلَى الحَقِّ مَتَى ظَهَرَ أَمَامَنَا، فَلْنَقْبَلِ الصَّوَابَ بِفَرَحٍ». ابْتَسَمَ مَازِنٌ مُقْتَنِعاً، وَشَرَعَ مَعَ سُرُورٍ فِي حَفْرِ السَّاقِيَةِ بِنَشَاطٍ.",
