          "content": "حَفِظَ شَابٌّ آيَاتِ القُرْآنِ فِي صَدْرِهِ، فَصَارَ إِذَا مَرَّ بِآيَةٍ تَأْمُرُ بِالعَفْوِ عَفَا عَمَّنْ أَسَاءَ إِلَيْهِ، وَإِذَا مَرَّ بِآيَةٍ تَأْمُرُ بِإِتْقَانِ العَمَلِ أَتْقَنَ صَنْعَتَهُ حَتَّى صَارَ النَّاسُ يَقُولُونَ: «رَأَيْنَا أَخْلَاقَ القُرْآنِ تَمْشِي عَلَى الأَرْضِ!». عِنْدَ الصَّالِحِينَ وَأَهْلِ البَصِيرَةِ يَرْتَفِعُ قَدْرُ حَامِلِ القُرْآنِ العَامِلِ بِهِ بِقَدْرِ مَا يَظْهَرُ نُورُ الآيَاتِ فِي صِدْقِهِ وَأَمَانَتِهِ، لَا بِمُجَرَّدِ تَزْيِينِ صَوْتِهِ دُونَ عَمَلٍ.\n\nوَفِي أَرْضِ النَّحْوِ، نُثَنِّي بِالرُّكْنِ الثَّانِي مِنَ المَرْفُوعَاتِ وَهُوَ «الخَبَرُ»؛ الِاسْمُ المَرْفُوعُ الَّذِي يُكْمِلُ مَعْنَى المُبْتَدَأِ وَيُوَضِّحُ مَا يُخْبَرُ عَنْهُ:\n\n▪ عَلَامَاتُ رَفْعِ الخَبَرِ المُفْرَدِ: يُرْفَعُ بِالضَّمَّةِ لِلمُفْرَدِ مِثْلَ «الطَّالِبُ مُجْتَهِدٌ» وَلِجَمْعِ المُؤَنَّثِ السَّالِمِ مِثْلَ «المُعَلِّمَاتُ مُجْتَهِدَاتٌ»، وَبِالأَلِفِ لِلمُثَنَّى مِثْلَ «الطَّالِبَانِ نَشِيطَانِ»، وَبِالوَاوِ لِجَمْعِ المُذَكَّرِ السَّالِمِ مِثْلَ «مُجْتَهِدُونَ».\n\n▪ الخَبَرُ الجُمْلَةُ وَشِبْهُ الجُمْلَةِ: قَدْ يَأْتِي الخَبَرُ جُمْلَةً فِعْلِيَّةً أَوِ اسْمِيَّةً مِثْلَ «الطَّالِبُ يُذَاكِرُ بِجِدٍّ»، أَوْ شِبْهَ جُمْلَةٍ مِثْلَ «الطَّالِبُ فِي المَدْرَسَةِ».\n\n▪ التَّطْبِيقُ العَمَلِيُّ: طَابِقْ كُلَّ مُبْتَدَأٍ بِخَبَرٍ يُنَاسِبُهُ فِي العَدَدِ وَأَعْرِبِ الخَبَرَ بِعَلَامَتِهِ الصَّحِيحَةِ فِي المُفْرَدِ وَالمُثَنَّى وَالجَمْعِ.",
          "questions": []
