          "content": "تَنْقَسِمُ الإِطَالَةُ العِلْمِيَّةُ إِلَى نَوْعَيْنِ لِكُلٍّ مِنْهُمَا تَوْقِيتُهُ الدَّقِيقُ: الإِطَالَةُ الدِّينَامِيكِيَّةُ (الحَرَكِيَّةُ) وَتُؤَدَّى بِأَرْجَحَةٍ وَمَدٍّ مُتَكَرِّرٍ قَبْلَ التَّمْرِينِ لِتَنْبِيهِ العَضَلَاتِ، وَالإِطَالَةُ الثَّابِتَةُ وَتُؤَدَّى بِالثَّبَاتِ الهَادِئِ فِي أَقْصَى مَدًى مُرِيحٍ (٢٠ – ٣٠ ثَانِيَةً دُونَ أَلَمٍ حَادٍّ) بَعْدَ التَّمْرِينِ لِإِعَادَةِ الأَلْيَافِ العَضَلِيَّةِ لِطُولِهَا الطَّبِيعِيِّ وَتَفْرِيغِ التَّوَتُّرِ.\n\n▪ الهَدَفُ وَالزَّمَنُ: (٥ – ٦ دَقَائِقَ خِتَامَ التَّمْرِينِ)؛ تَسْرِيعُ اسْتِشْفَاءِ العَضَلَاتِ، وَمَنْعُ التَّيَبُّسِ الصَّبَاحِيِّ، وَتَهْدِئَةُ النَّبْضِ وَالجِهَازِ العَصَبِيِّ بَعْدَ المَجْهُودِ.\n\n▪ التَّطْبِيقُ الحَرَكِيُّ: طَبِّقْ وَضْعِيَّةَ «اسْتِرْخَاءِ الطِّفْلِ» بِالجُلُوسِ عَلَى الكَعْبَيْنِ وَمَدِّ الذِّرَاعَيْنِ لِلأَمَامِ عَلَى الأَرْضِ مَعَ تَنَفُّسٍ بَطِيءٍ لِمُدَّةِ ٤٥ ثَانِيَةً لِإِرَاحَةِ كَامِلِ عَضَلَاتِ الظَّهْرِ.",
