          "content": "1- تركيبُ النّيكليوتيدة: يتكوّنُ خيطُ الحمضِ النّوويِّ منقوصِ الأكسجينِ مِنْ تَتَالِي وحداتٍ بنائيّةٍ تُسمّى النّيكليوتيدات، تضمُّ كلُّ واحدةٍ مِنْهَا سكّراً خماسيّاً وفوسفاتاً وَقَاعِدَةً آزُوتِيَّةً.\n\n2- تكاملُ القواعدِ الآزوتيّةِ الأَرْبَعِ: ترتبطُ القواعدُ فِي السّلسلتينِ المتقابلتينِ وفقَ قاعدةٍ ثَابِتَةٍ، فيرتبطُ الأدينينُ دائماً بالتّايمين، ويرتبطُ الغوانينُ دائماً بالسّيتوزين.\n\n3- نموذجُ الحلزونِ المُزْدَوِجِ: تلتفُّ السّلسلتانِ المتكاملتانِ حولَ بعضِهما فِي الفضاءِ عَلَى شَكْلِ سُلَّمٍ حَلَزُونِيٍّ مُزْدَوِجٍ تمثّلُ القواعدُ درجاتِه.",
