          "content": "لَاحَظَ مُزَارِعٌ أَنَّ زَهْرَةَ دَوَّارِ الشَّمْسِ تُدِيرُ قُرْصَهَا الذَّهَبِيَّ تِلْقَائِيّاً مَعَ حَرَكَةِ الشَّمْسِ مِنَ المَشْرِقِ إِلَى المَغْرِبِ دُونَ أَنْ يُعَلِّمَهَا أَحَدٌ! أَوْدَعَ اللَّهُ فِي أَعْمَاقِ كُلِّ إِنْسَانٍ بُوصَلَةً دَاخِلِيَّةً صَافِيَةً تُسَمَّى «الفِطْرَةَ»؛ فَهِيَ تَمِيلُ بِطَبْعِهَا السَّلِيمِ إِلَى مَعْرِفَةِ خَالِقِهَا، وَتَسْتَحْسِنُ الصِّدْقَ وَالعَدْلَ وَالرَّحْمَةَ، وَتَنْفِرُ مِنَ الكَذِبِ وَالظُّلْمِ قَبْلَ أَنْ يُلَوِّثَهَا الغُبَارُ. تَأَمَّلْ كَيْفَ عَبَّرَ أَمِيرُ المُؤْمِنِينَ عَلَيْهِ السَّلَامُ عَنْ مُهِمَّةِ الرُّسُلِ فِي إِيقَاظِ هَذِهِ الفِطْرَةِ الكَامِنَةِ فِي النُّفُوسِ:\n\n«وَيُذَكِّرُوهُمْ مَنْسِيَّ نِعْمَتِهِ، وَيَسْتَأْدُوهُمْ مِيثَاقَ فِطْرَتِهِ».\n\nتَذَوَّقْ جَمَالَ البَلَاغَةِ حِينَ نَحْذِفُ أَدَاةَ التَّشْبِيهِ فِي التَّشْبِيهِ البَلِيغِ فَنَقُولُ: «العِلْمُ نُورٌ» وَ«الفِطْرَةُ بُوصَلَةٌ»؛ كَأَنَّ الشَّيْئَيْنِ صَارَا حَقِيقَةً وَاحِدَةً لِشِدَّةِ التَّطَابُقِ! وَفِي مَرْسَمِ الفَنِّ، نَتَعَلَّمُ رَسْمَ الزَّهْرَةِ الهَنْدَسِيَّةِ السُّدَاسِيَّةِ بِاسْتِعْمَالِ الدَّوَائِرِ المُتَقَاطِعَةِ كَمَا بُنِيَتْ خَلَايَا النَّحْلِ الفِطْرِيَّةُ المُدْهِشَةُ.\n\n▪ اكْتُبْ بِخَطِّ النَّسْخِ الصَّافِي تَشْبِيهاً بَلِيغاً: «الفِطْرَةُ سِرَاجٌ، وَالقُرْآنُ رَبِيعُ القُلُوبِ».\n\n▪ التَّطْبِيقُ العَمَلِيُّ: ارْسُمْ دَائِرَةً مَرْكَزِيَّةً وَسِتَّةَ أَقْوَاسٍ مُتَسَاوِيَةٍ بِدَاخِلِهَا لِتَظْهَرَ الزَّهْرَةُ السُّدَاسِيَّةُ، وَتَدَرَّبْ فِي خَطِّ النَّسْخِ عَلَى اتِّسَاعِ صُحُونِ (ب، ت، ث).",
