          "content": "تُنْتِجُ العَضَلَاتُ القُوَّةَ بِثَلَاثِ طُرُقٍ مِيكَانِيكِيَّةٍ: الِانْقِبَاضُ الثَّابِتُ (الإِيزُومِتْرِيُّ) حَيْثُ تَشْتَدُّ العَضَلَةُ وَتُوَلِّدُ قُوَّةً دُونَ أَنْ يَتَغَيَّرَ طُولُهَا أَوْ يَتَحَرَّكَ المَفْصِلُ (كَالثَّبَاتِ فِي وَضْعِ الجِسْرِ)، وَالِانْقِبَاضُ المَرْكَزِيُّ حَيْثُ تَقْصُرُ العَضَلَةُ لِتَرْفَعَ وَزْنَ الجِسْمِ ضِدَّ الجَاذِبِيَّةِ، وَالِانْقِبَاضُ اللَّامَرْكَزِيُّ حَيْثُ تَطُولُ العَضَلَةُ بِبُطْءٍ وَتُقَاوِمُ الجَاذِبِيَّةَ أَثْنَاءَ الهُبُوطِ المَحْسُوبِ.\n\n▪ الهَدَفُ وَالزَّمَنُ: (٥ دَقَائِقَ)؛ تَقْوِيَةُ الأَوْتَارِ وَالأَرْبِطَةِ بِأَعْلَى دَرَجَاتِ الأَمَانِ، وَمُضَاعَفَةُ التَّحَكُّمِ العَصَبِيِّ فِي سُرْعَةِ الصُّعُودِ وَالهُبُوطِ.\n\n▪ التَّطْبِيقُ الحَرَكِيُّ: نَفِّذْ تَمْرِينَ «الجِسْرِ الوَرِكِيِّ الثَّابِتِ» اسْتِلْقَاءً عَلَى الظَّهْرِ بِرَفْعِ الحَوْضِ حَتَّى يَسْتَقِيمَ مَعَ الرُّكْبَتَيْنِ وَالكَتِفَيْنِ وَالثَّبَاتِ ٣٠ ثَانِيَةً (٣ مَجْمُوعَاتٍ).",
