          "content": "1- الطّورُ البينيُّ التّحضيريّ: تسبِقُ الخليّةُ انقسامَها بطورٍ بينيٍّ تَنْمُو فيهِ وتنسخُ خيطَها الوراثيَّ ليصبحَ كلُّ صبغيٍّ مكوناً مِنْ خيطينِ شقيقينِ (كُرُومَاتِيدَيْنِ).\n\n2- آليّةُ التّضاعفِ نصفِ المُحَافِظِ: يفكُّ أنزيمُ الهيليكازِ ارتباطَ سلسلتَيِ الحلزونِ المُزْدَوِجِ، وَيَبْنِي أنزيمُ البوليميرازِ أمامَ كلِّ سلسلةٍ قديمةٍ سلسلةً جديدةً مكمّلةً لَهَا.\n\n3- حفظُ المعلومةِ الوراثيّة: ينتجُ عَنِ التّضاعفِ جزيئتانِ وراثيّتانِ متطابقتانِ تماماً، تَحْتَوِي كلُّ واحدةٍ مِنْهُمَا عَلَى سلسلةٍ أصليّةٍ وَسِلْسِلَةٍ جَدِيدَةٍ.",
