          "content": "عَضَلَاتُ المَرْكَزِ لَا تَقْتَصِرُ عَلَى عَضَلَةِ البَطْنِ السَّطْحِيَّةِ، بَلْ تَشْمَلُ حِزَاماً أُسْطُوَانِيّاً يُحِيطُ بِالعَمُودِ الفِقْرِيِّ مِنَ الأَمَامِ وَالجَانِبَيْنِ وَالظَّهْرِ وَالحَوْضِ؛ وَهَذَا المَرْكَزُ هُوَ الجِسْرُ الَّذِي يَنْقُلُ القُوَّةَ بَيْنَ الأَطْرَافِ السُّفْلِيَّةِ وَالعُلْوِيَّةِ وَيَحْمِي فِقْرَاتِ الظَّهْرِ مِنَ الِانْثِنَاءِ الخَاطِئِ.\n\n▪ الهَدَفُ وَالزَّمَنُ: (٦ دَقَائِقَ)؛ بِنَاءُ جِدَارٍ عَضَلِيٍّ وَاقٍ لِلعَمُودِ الفِقْرِيِّ، وَتَحْسِينُ التَّوَازُنِ، وَزِيَادَةُ قُوَّةِ جَمِيعِ الحَرَكَاتِ الرِّيَاضِيَّةِ.\n\n▪ التَّطْبِيقُ الحَرَكِيُّ: قَوِّ الجِدَارَ الجَانِبِيَّ لِلجِذْعِ بِتَمْرِينِ «اللَّوْحِ الجَانِبِيِّ» عَلَى السَّاعِدِ وَالرُّكْبَتَيْنِ (أَوِ القَدَمَيْنِ) لِمُدَّةِ ٢٠ ثَانِيَةً لِكُلِّ جَانِبٍ (٣ مَجْمُوعَاتٍ).",
