          "content": "1- نسخُ الرّسولِ داخلَ النّواة: يقومُ أنزيمُ النّسخِ بقراءةِ المورّثةِ فِي النّواةِ ليصنعَ شريطاً مفرداً هُوَ الحمضُ الرّيبيُّ الرّسولُ الَّذِي يخرجُ عبرَ ثقوبِ النّواةِ إِلَى الهَيُولَى حاملاً الشَّفْرَةَ الثُّلَاثِيَّةَ.\n\n2- التّرجمةُ فِي الرّيبوزوم: يقرأُ الرّيبوزومُ الشّريطَ الرّسولَ بمساعدةِ الجزيئاتِ النّاقلة، فيربطُ الأحماضَ الأمينيّةَ بالترتيبِ لصنعِ البروتينِ الوظيفيّ.\n\n3- الطّفراتُ الوراثيّة: الطّفرةُ هِيَ تغيّرٌ مفاجئٌ فِي حروفِ المورّثةِ بالاستبدالِ أَوْ الحذفِ أَوْ الإِضَافَةِ، ممّا قَدْ يغيّرُ البروتينَ النّاتجَ وَيُغَيِّرُ الصِّفَةَ.",
