          "content": "جَلَسَ صَبِيٌّ فِي العَاشِرَةِ يَتَصَفَّحُ أَلْبُومَ صُوَرِهِ مُنْذُ كَانَ رَضِيعاً لَا يَقْدِرُ أَنْ يُمْسِكَ المِلْعَقَةَ بِيَدِهِ وَلَا أَنْ يَخْطُوَ خُطْوَةً وَاحِدَةً دُونَ أَنْ تُسْنِدَهُ يَدُ أُمِّهِ وَأَبِيهِ، وَتَذَكَّرَ سَهَرَهُمَا بِجَانِبِهِ لَيَالِيَ المَرَضِ حَتَّى عُوفِيَ وَاشْتَدَّ عُودُهُ! فِي وَصَايَا اللَّهِ وَهَدْيِ أَهْلِ البَيْتِ عَلَيْهِمُ السَّلَامُ يَقْتَرِنُ شُكْرُ الوَالِدَيْنِ بِشُكْرِ الخَالِقِ مُبَاشَرَةً؛ لِأَنَّهُمَا السَّبَبُ الأَوَّلُ لِرِعَايَتِكَ وَتَعْلِيمِكَ:\n\n«بِرُّ الوَالِدَيْنِ وَاجِبٌ... لَا تَمْلَأْ عَيْنَيْكَ مِنَ النَّظَرِ إِلَيْهِمَا إِلَّا بِرَحْمَةٍ وَرِقَّةٍ، وَلَا تَرْفَعْ صَوْتَكَ فَوْقَ أَصْوَاتِهِمَا».\n\nيُحَلِّقُ خَيَالُكَ الشُّعُورِيُّ لِيَعِيشَ مَكَانَ وَالِدَيْكَ سَاعَةً وَاحِدَةً، فَتُدْرِكَ مِقْدَارَ الجُهْدِ الخَفِيِّ الَّذِي يَبْذُلَانِهِ كُلَّ يَوْمٍ مِنْ أَجْلِكَ! وَمِنْ هَذَا الوَعْيِ تَسْتَنْتِجُ الفَرْقَ الدَّقِيقَ بَيْنَ «الطَّاعَةِ الجَافَّةِ» وَهِيَ تَنْفِيذُ الأَمْرِ بِتَذَمُّرٍ وَتَقْطِيبِ جَبِينٍ، وَ«البِرِّ الرَّحِيمِ» وَهُوَ المُبَادَرَةُ بِالخِدْمَةِ مَعَ خَفْضِ الصَّوْتِ وَنَظْرَةِ المَحَبَّةِ وَالدُّعَاءِ الصَّادِقِ لَهُمَا.\n\n▪ التَّطْبِيقُ العَمَلِيُّ: اسْتَعْرِضْ شَرِيطَ النُّمُوِّ العُمُرِيِّ مِنَ المَهْدِ إِلَى العَاشِرَةِ، وَاخْتَرْ أَرْقَى عِبَارَاتِ الأَدَبِ وَالبِرِّ فِي المَوَاقِفِ العَائِلِيَّةِ.",
