          "content": "صَعِدَ مُتَسَلِّقٌ مَغْرُورٌ إِلَى تَلَّةٍ عَالِيَةٍ، فَصَارَ يَرَى النَّاسَ فِي الوَادِي صِغَاراً كَالنَّمْلِ فَظَنَّ أَنَّهُ أَعْظَمُ مِنْهُمْ، وَلَمْ يَنْتَبِهْ أَنَّ النَّاسَ فِي الوَادِي يَرَوْنَهُ هُوَ أَيْضاً نُقْطَةً صَغِيرَةً مِنْ بَعِيدٍ! دَاءُ الكِبْرِ حِجَابٌ يُعْمِي صَاحِبَهُ عَنْ رُؤْيَةِ عُيُوبِهِ وَيَمْنَعُهُ مِنَ الِاسْتِفَادَةِ مِنْ عِلْمِ الآخَرِينَ؛ فَمَنْ تَكَبَّرَ عَنِ السُّؤَالِ بَقِيَ جَاهِلاً، وَمَنْ تَوَاضَعَ لِلحَقِّ ارْتَفَعَ قَدْرُهُ.\n\nوَفِي أَرْضِ النَّحْوِ، نَدْرُسُ اليَوْمَ المَرْفُوعَ الثَّالِثَ وَهُوَ «الفَاعِلُ»؛ الِاسْمُ المَرْفُوعُ الَّذِي يَدُلُّ عَلَى مَنْ قَامَ بِالفِعْلِ فِي الجُمْلَةِ الفِعْلِيَّةِ وَيَأْتِي بَعْدَهُ:\n\n▪ عَلَامَاتُ رَفْعِ الفَاعِلِ الظَّاهِرِ: يُرْفَعُ بِالضَّمَّةِ لِلمُفْرَدِ مِثْلَ «كَتَبَ الطَّالِبُ» وَلِجَمْعِ المُؤَنَّثِ السَّالِمِ مِثْلَ «المُعَلِّمَاتُ»، وَبِالأَلِفِ لِلمُثَنَّى مِثْلَ «الطَّالِبَانِ»، وَبِالوَاوِ لِجَمْعِ المُذَكَّرِ السَّالِمِ مِثْلَ «المُعَلِّمُونَ».\n\n▪ الفَاعِلُ الضَّمِيرُ: قَدْ يَأْتِي ضَمِيراً مُتَّصِلاً مِثْلَ التَّاءِ فِي «كَتَبْتُ» وَالوَاوِ فِي «كَتَبُوا الوَاجِبَ»، أَوْ ضَمِيراً مُسْتَتِراً يُقَدَّرُ مِنَ الفِعْلِ مِثْلَ «اذْهَبْ» وَتَقْدِيرُهُ أَنْتَ.\n\n▪ التَّطْبِيقُ العَمَلِيُّ: حَدِّدِ الفَاعِلَ وَبَيِّنْ صُورَتَهُ وَعَلَامَةَ رَفْعِهِ فِي الجُمَلِ: (يُدَرِّسُ المُعَلِّمُ الطُّلَّابَ — كَتَبُوا الوَاجِبَ — اذْهَبْ إِلَى المَدْرَسَةِ).",
          "questions": []
