          "content": "أَرَادَ سُرُورٌ أَنْ يَنْقُلَ نَبْتَةَ الظِّلِّ الرَّقِيقَةَ لِيَضَعَهَا فِي وَسَطِ الشَّمْسِ الحَارِقَةِ فَقَطْ لِأَنَّ شَكْلَ أَصِيصِهَا الفَخَّارِيِّ أَعْجَبَهُ هُنَاكَ، مُهْمِلاً طَبِيعَةَ النَّبْتَةِ وَمَا يُنَاسِبُهَا. سَأَلَتْهُ حُورُ: «مَاذَا يَحْدُثُ لِنَبْتَةِ الظِّلِّ إِنْ تَرَكْنَاهَا تَحْتَ شَمْسِ الظَّهِيرَةِ؟». أَجَابَ سُرُورٌ بَعْدَ تَفْكِيرٍ: «تَحْتَرِقُ أَوْرَاقُهَا وَتَذْبُلُ». قَالَتْ حُورُ: «لِهَذَا نَحْتَاجُ إِلَى الحِكْمَةِ الَّتِي تُحْيِي القُلُوبَ وَتُعَلِّمُنَا وَضْعَ كُلِّ شَيْءٍ فِي مَوْضِعِهِ الصَّحِيحِ لَا كَمَا تَشْتَهِي أَمْزِجَتُنَا؛ وَالحَكِيمُ مَنْ يَجْمَعُ بَيْنَ احْتِرَامِ قَوَانِينِ الطَّبِيعَةِ الَّتِي وَضَعَهَا اللَّهُ وَبَيْنَ صَفَاءِ نِيَّتِهِ وَبَصِيرَتِهِ». اقْتَنَعَ سُرُورٌ، وَوَضَعَ الأَصِيصَ تَحْتَ ظِلِّ العَرِيشَةِ حَيْثُ تَنْمُو النَّبْتَةُ بِأَمَانٍ.",
