          "content": "▪ مُخْتَبَرُ اليَدَيْنِ: ارْسُمْ مُسْتَقِيمَيْنِ مُتَوَازِيَيْنِ وَاقْطَعْهُمْ بِمُسْتَقِيمٍ ثَالِثٍ، قِسِ الزَّوَايَا بِالمِنْقَلَةِ.\n\n▪ القَاعِدَةُ وَالشَّرْحُ: الزَّوَايَا المُتَبَادَلَةُ وَالمُتَنَاظِرَةُ مُتَسَاوِيَةٌ. مَجْمُوعُ زَوَايَا المُثَلَّثِ 180 دَرَجَةً.\n\n▪ مِثَالٌ مَحْلُولٌ: مُثَلَّثٌ زَوَايَاهُ 60، 60، س. مَا س؟ الجَوَابُ: 60 دَرَجَةً (مُثَلَّثٌ مُتَسَاوِي الأَضْلَاعِ).",
