          "content": "لَا يَشْتَرِي الصَّائِغُ سَبِيكَةَ ذَهَبٍ مِنْ بَرِيقِهَا الخَارِجِيِّ وَحْدَهُ، بَلْ يُعَرِّضُهَا لِحَجَرِ المِحَكِّ لِيَعْرِفَ مَعْدِنَهَا الحَقِيقِيَّ قَبْلَ أَنْ يَدْفَعَ ثَمَنَهَا! وَكَذَلِكَ يَضَعُ الحُكَمَاءُ وَأَهْلُ البَيْتِ عَلَيْهِمُ السَّلَامُ مَنْهَجاً عَقْلِيّاً فَاحِصاً لِاخْتِيَارِ الصَّدِيقِ المُقَرَّبِ؛ فَلَا تَمْنَحْ ثِقَتَكَ الكَامِلَةَ وَسِرَّكَ إِلَّا بَعْدَ اخْتِبَارِ أَخْلَاقِ رَفِيقِكَ فِي ثَلَاثَةِ مَوَاقِفَ حَقِيقِيَّةٍ:\n\n«لَا تَصْحَبَنَّ أَحَداً حَتَّى تَخْتَبِرَهُ عِنْدَ ثَلَاثٍ: عِنْدَ غَضَبِهِ، وَعِنْدَ طَمَعِهِ، وَفِي سَفَرِهِ».\n\nتُسَلِّطُ شُعْلَةُ الفَهْمِ الضَّوْءَ عَلَى سِرِّ هَذِهِ المِحَكَّاتِ الثَّلَاثَةِ: الإِنْسَانُ فِي حَالَةِ الرِّضَا وَالرَّاحَةِ يَسْهُلُ عَلَيْهِ التَّجَمُّلُ، أَمَّا عِنْدَ الغَضَبِ فَيَظْهَرُ مِقْدَارُ حِلْمِهِ وَإِنْصَافِهِ فَلَا يَفْجُرُ فِي الخُصُومَةِ، وَعِنْدَ الطَّمَعِ وَالمُنَافَسَةِ تَظْهَرُ أَمَانَتُهُ وَإِيثَارُهُ، وَفِي السَّفَرِ وَالعَمَلِ المُشْتَرَكِ الطَّوِيلِ تَسْقُطُ الأَقْنِعَةُ فَتَظْهَرُ الطِّبَاعُ الأَصِيلَةُ!\n\n▪ التَّطْبِيقُ العَمَلِيُّ: طَبِّقْ مِحَكَّاتِ الِاخْتِبَارِ الثَّلَاثَةَ (الغَضَبَ، المُنَافَسَةَ، الرِّحْلَةَ المُشْتَرَكَةَ) عَلَى مَوَاقِفَ افْتِرَاضِيَّةٍ لِتَخْتَارَ الرَّفِيقَ الأَجْدَرَ بِالثِّقَةِ.",
