          "content": "إِذَا تَلَا حَرْفَ المَدِّ سُكُونٌ أَصْلِيٌّ ثَابِتٌ وَصْلاً وَوَقْفاً لَزِمَ مَدُّهُ ٦ حَرَكَاتٍ مُشْبَعَةٍ (المَدُّ اللَّازِمُ الكَلِمِيُّ وَالحَرْفِيُّ، المُثَقَّلُ وَالمُخَفَّفُ)، أَمَّا إِنْ عَرَضَ السُّكُونُ لِأَجْلِ الوَقْفِ فَقَطْ سُمِّيَ «عَارِضاً لِلسُّكُونِ» (أَوْ «مَدَّ لِينٍ» بَعْدَ الوَاوِ وَاليَاءِ السَّاكِنَتَيْنِ المَفْتُوحِ مَا قَبْلَهُمَا) وَيُمَدُّ ٢ أَوْ ٤ أَوْ ٦ حَرَكَاتٍ.\n\n▪ التَّدْرِيبُ الصَّوْتِيُّ: اهْجُ فَوَاتِحَ السُّوَرِ الثُّلَاثِيَّةَ المَجْمُوعَةَ فِي «نَقَصَ عَسَلُكُمْ» بِمَدٍّ لَازِمٍ مِنْ ٦ حَرَكَاتٍ مَعَ مُرَاعَاةِ الإِدْغَامِ وَالإِخْفَاءِ فِي «الْمْ»، وَ«طسْمْ»، وَ«كَهيعْصْ».",
