              "answer": "فِي انْثِنَاءِ الوَرِكِ يَرْجِعُ الحَوْضُ لِلخَلْفِ وَيَبْقَى العَمُودُ الفِقْرِيُّ مُسْتَقِيماً كَقِطْعَةٍ وَاحِدَةٍ، أَمَّا انْحِنَاءُ الظَّهْرِ فَيُقَوِّسُ الفِقْرَاتِ وَيُؤْذِيهَا."
