          "content": "1- الفحوصاتُ الجنينيّةُ المبكّرة: يراقبُ الأطبّاءُ سلامةَ الجنينِ بالأمواجِ فوقَ الصّوتيّةِ وتحليلِ السّائلِ الأمنيوسيِّ للكشفِ المبكّرِ عَنِ الشّذوذاتِ الصِّبْغِيَّةِ وَالجِينِيَّةِ.\n\n2- الأمراضُ الجينيّة: تنشأُ عَنْ طفرةٍ فِي مورّثةٍ وَاحِدَةٍ، مثلَ فقرِ الدّمِ المنجليِّ الَّذِي يغيّرُ شكلَ الكريّةِ الحمراءِ إِلَى هِلَالٍ، ومرضِ التّليّفِ الكيسيّ.\n\n3- البصمةُ الوراثيّة: لكلِّ إنسانٍ تتابعٌ فريدٌ فِي حمضِهِ النّوويِّ يُفصلُ بالهجرةِ الكهربائيّةِ ويُستخدمُ كبصمةٍ وراثيّةٍ لَا تتكرّرُ عندَ غيرِه.",
