          "content": "عِنْدَ الغُرُوبِ، تَرَكَ سُرُورٌ بَابَ قُنِّ الدَّجَاجِ مَفْتُوحاً، وَأَلْقَى قُشُورَ الفَاكِهَةِ مَكْشُوفَةً قُرْبَ المَمَرِّ قَائِلاً بِلَا مُبَالَاةٍ: «لَا بَأْسَ، الوَقْتُ طَوِيلٌ وَسَأُرَتِّبُ كُلَّ شَيْءٍ لَاحِقاً!»، مُسْتَسْلِماً لِلغَفْلَةِ وَطُولِ الأَمَلِ. وَفِي الصَّبَاحِ وَجَدَا الدَّجَاجَ قَدْ بَعْثَرَ القُشُورَ وَأَتْلَفَ شَتَلَاتِ النَّعْنَاعِ الصَّغِيرَةَ. سَاعَدَتْهُ حُورُ فِي إِصْلَاحِ الحَوْضِ وَقَالَتْ: «الغَفْلَةُ وَطُولُ الأَمَلِ يُطْفِئَانِ نُورَ الِانْتِبَاهِ فَيَقَعُ الخَطَأُ، أَمَّا التَّفَكُّرُ فَهُوَ دَلِيلُ العَاقِلِ الَّذِي يُبْصِرُ عَوَاقِبَ أَفْعَالِهِ قَبْلَ وُقُوعِهَا؛ فَالعَقْلُ فِي جَسَدِنَا يُشْبِهُ القَمَرَ المُنِيرَ، يَسْتَمِدُّ ضَوْءَهُ مِنَ القَلْبِ الصَّافِي لِيُرْشِدَ جَوَارِحَنَا إِلَى التَّصَرُّفِ السَّلِيمِ».",
