          "content": "فِي مَعْرِضِ المَدْرَسَةِ العِلْمِيِّ، رَأَى سُرُورٌ مُسَابَقَةً عَشْوَائِيَّةً يَدْفَعُ فِيهَا المُشَارِكُونَ مَصْرُوفَهُمْ طَمَعاً فِي الفَوْزِ بِلُعْبَةٍ إِلِكْتُرُونِيَّةٍ بَرَّاقَةٍ دُونَ أَيِّ جُهْدٍ عِلْمِيٍّ، فَمَالَتْ نَفْسُهُ لِلمُجَازَفَةِ بِمَصْرُوفِهِ كُلِّهِ حُبّاً فِي اقْتِنَائِهَا. جَذَبَتْهُ حُورُ نَحْوَ رُكْنِ المُبْتَكَرَاتِ المَدْرَسِيَّةِ وَقَالَتْ: «التَّعَلُّقُ الشَّدِيدُ بِالمُغْرِيَاتِ المَادِّيَّةِ يَجُرُّ صَاحِبَهُ إِلَى الخَسَارَةِ وَالبَلَاءِ، بَيْنَمَا تَتَحَقَّقُ السَّلَامَةُ الحَقِيقِيَّةُ بِطَلَبِ كَمَالِ العَقْلِ؛ وَذَلِكَ حِينَ نَجْمَعُ أَخْلَاقَ دِينِنَا الحَنِيفِ مَعَ أَدَوَاتِ العِلْمِ النَّافِعِ فَنَحْفَظُ أَمْوَالَنَا وَأَوْقَاتَنَا فِي مَا يُفِيدُ».",
