          "content": "خَرَجَ سَامِرٌ بَعْدَ المَعْرِضِ يَحْمِلُ مُجَسَّماً فَلَكِيّاً جَمِيلاً أَهْدَاهُ إِيَّاهُ وَالِدُهُ، فَنَظَرَ إِلَيْهِ سُرُورٌ بِحَسْرَةٍ وَضَاقَ صَدْرُهُ مُتَمَنِّياً لَوْ كَانَ المُجَسَّمُ لَهُ وَحْدَهُ، فَغَابَ بِشْرُهُ وَشَعَرَ بِانْقِبَاضٍ فِي قَلْبِهِ. لَمَسَتْ حُورُ تَغَيُّرَ حَالِهِ فَقَالَتْ لَهُ بِحَنَانٍ: «لَا تَدَعِ الحَسَدَ وَحُبَّ المَظَاهِرِ يَدْخُلَانِ قَلْبَكَ فَيَجْلِبَا لَهُ الهَمَّ وَالبَلْوَى؛ إِنَّ أَجْمَلَ العَافِيَةِ هِيَ رَاحَةُ القَلْبِ بِنَقَائِهِ مِنَ الحَسَدِ وَالغِلِّ لِلآخَرِينَ، وَهِيَ تُشْبِهُ تَمَاماً عَافِيَةَ البَدَنِ حِينَ تَتَوَازَنُ طَبَائِعُهُ الأَرْبَعَةُ بِالغِذَاءِ الطَّبِيعِيِّ الطَّيِّبِ فَيَدُومُ نَشَاطُهُ وَصِحَّتُهُ». دَعَا سُرُورٌ لِزَمِيلِهِ بِالبَرَكَةِ، فَشَعَرَ بِانْشِرَاحٍ فَوْرِيٍّ فِي صَدْرِهِ.",
