          "content": "إِذَا طُلِبَ مِنْكَ أَنْ تَحْكُمَ فِي مُسَابَقَةٍ مَدْرَسِيَّةٍ أَوْ خِلَافٍ بَيْنَ فَرِيقَيْنِ، فَمَا الصِّفَاتُ الَّتِي يَجِبُ أَنْ تَتَحَلَّى بِهَا قَبْلَ الجُلُوسِ لِلحُكْمِ؟ رَسَمَ الإِمَامُ عَلِيٌّ عَلَيْهِ السَّلَامُ مَلَامِحَ الحَكَمِ العَادِلِ بِدِقَّةٍ بَاهِرَةٍ تَصْلُحُ مِيزَاناً لِكُلِّ زَمَانٍ:\n\n«اخْتَرْ لِلحُكْمِ بَيْنَ النَّاسِ أَفْضَلَ رَعِيَّتِكَ فِي نَفْسِكَ؛ مِمَّنْ لَا تَضِيقُ بِهِ الأُمُورُ، وَلَا تُمَحِّكُهُ الخُصُومُ، وَلَا يَتَمَادَى فِي الزَّلَّةِ، وَلَا يَحْصَرُ مِنَ الفَيْءِ إِلَى الحَقِّ إِذَا عَرَفَهُ».\n\nيَتَخَيَّلُ ذِهْنُكَ الحَكَمَ القَوِيَّ الأَمِينَ مِنْ خِلَالِ أَرْبَعِ صُوَرٍ نَفْسِيَّةٍ عَمِيقَةٍ: «لَا تَضِيقُ بِهِ الأُمُورُ» أَيْ وَاسِعُ الصَّدْرِ صَبُورٌ عَلَى فَحْصِ الأَدِلَّةِ، وَ«لَا تُمَحِّكُهُ الخُصُومُ» أَيْ لَا يَسْتَفِزُّهُ جِدَالُ المُتَخَاصِمِينَ فَيَحْكُمَ بِغَضَبٍ، وَ«لَا يَتَمَادَى فِي الزَّلَّةِ» أَيْ لَا يَسْتَكْبِرُ إِذَا أَخْطَأَ، وَ«يَرْجِعُ إِلَى الحَقِّ فَوْراً» مَتَى ظَهَرَ لَهُ البُرْهَانُ دُونَ عِنَادٍ!\n\n▪ التَّطْبِيقُ العَمَلِيُّ: اجْلِسْ فِي مِنَصَّةِ التَّحْكِيمِ العِلْمِيِّ، وَطَبِّقِ الصِّفَاتِ الأَرْبَعَ فِي مَسْأَلَةٍ شَائِكَةٍ تَتَدَاخَلُ فِيهَا الأَقْوَالُ حَتَّى تَصِلَ إِلَى الحَقِيقَةِ البُرْهَانِيَّةِ.",
