          "content": "العَضَلَةُ كَالمُحَرِّكِ الحَيَوِيِّ لَا تَعْمَلُ وَلَا تُرَمَّمُ إِلَّا بِوَقُودٍ نَقِيٍّ وَمَاءٍ كَافٍ؛ فَالسُّكَّرِيَّاتُ الطَّبِيعِيَّةُ المُعَقَّدَةُ وَالفَوَاكِهُ تَمْنَحُ الغَلِيكُوجِينَ المُحَرِّكَ لِلجُهْدِ، وَالبُرُوتِينَاتُ الطَّبِيعِيَّةُ تُرَمِّمُ الأَلْيَافَ العَضَلِيَّةَ وَتُنَمِّيهَا بَعْدَ التَّمْرِينِ، وَالدُّهْنُ الطَّبِيعِيُّ كَزَيْتِ الزَّيْتُونِ وَالمُكَسَّرَاتِ يَحْفَظُ المَفَاصِلَ وَالهُرْمُونَاتِ، بَيْنَمَا يُسَبِّبُ فِقْدَانُ ٢٪ فَقَطْ مِنْ مَاءِ الجِسْمِ بِالتَّعَرُّقِ هُبُوطاً حَادّاً فِي التَّرْكِيزِ وَالقُوَّةِ العَضَلِيَّةِ!\n\n▪ الهَدَفُ وَالزَّمَنُ: (٥ دَقَائِقَ وَعْيٍ وَسُلُوكٍ عَمَلِيٍّ)؛ تَغْذِيَةُ البَدَنِ بِالأَطْعِمَةِ الكَامِلَةِ غَيْرِ المُصَنَّعَةِ، وَتَنْظِيمُ مَوَاعِيدِ الطَّعَامِ وَالشُّرْبِ حَوْلَ التَّمْرِينِ الرِّيَاضِيِّ.\n\n▪ التَّطْبِيقُ الحَرَكِيُّ: تَعَرَّفْ عَلَى «وَجْبَةِ البِنَاءِ وَالتَّرْمِيمِ بَعْدَ التَّمْرِينِ» الَّتِي تَجْمَعُ بُرُوتِيناً طَبِيعِيّاً (كَالبَيْضِ، اللَّبَنِ الرَّائِبِ، البُقُولِيَّاتِ، السَّمَكِ) مَعَ كَرْبُوهِيدْرَاتٍ طَبِيعِيَّةٍ لِإِعَادَةِ مَلْءِ مَخَازِنِ العَضَلَاتِ.",
