          "content": "فِي يَوْمِ الجُمُعَةِ، شَعَرَ سُرُورٌ بِنَشَاطٍ وَصِحَّةٍ جَيِّدَةٍ، فَاسْتَلْقَى عَلَى الأَرِيكَةِ طَوَالَ العَصْرِ يَأْكُلُ الفَطَائِرَ الدَّسِمَةَ وَيَرْفُضُ مُرَافَقَةَ حُورَ فِي رِيَاضَةِ المَشْيِ وَالتَّمَدُّدِ، قَائِلاً: «أَنَا بِصِحَّةٍ مُمْتَازَةٍ وَأُرِيدُ أَنْ أُدَلِّلَ نَفْسِي بِالرَّاحَةِ التَّامَّةِ!». وَقَبْلَ المَسَاءِ شَعَرَ بِثِقَلٍ وَخُمُولٍ شَدِيدٍ فِي جِسْمِهِ. فَتَحَتْ حُورُ النَّافِذَةَ لِيَتَجَدَّدَ الهَوَاءُ وَقَالَتْ: «الرُّكُونُ إِلَى التَّرَفِ وَالخُمُولِ يُفْسِدُ نِعْمَةَ العَافِيَةِ يَا سُرُورُ؛ فَجِسْمُنَا يَحْتَاجُ إِلَى التَّوَازُنِ الدَّائِمِ بَيْنَ الرُّطُوبَةِ وَاليُبُوسَةِ، وَبَيْنَ الحَرَكَةِ النَّافِعَةِ وَالهُدُوءِ المُعْتَدِلِ، لِيَبْقَى حَيَوِيّاً وَصَافِيَ الذِّهْنِ».",
