          "content": "أَقَامَ وَالِدُهُمَا أُمْسِيَةً عِلْمِيَّةً فِي شُرْفَةِ المَنْزِلِ حَضَرَهَا أَسَاتِذَةٌ وَكِبَارٌ فِي السِّنِّ، فَسَبَقَهُمْ سُرُورٌ وَجَلَسَ فِي صَدْرِ المَكَانِ المُخَصَّصِ لِكِبَارِ الضُّيُوفِ ظَنّاً مِنْهُ أَنَّ ذَلِكَ يَرْفَعُ شَأْنَهُ، فَشَعَرَ الحَاضِرُونَ بِالحَرَجِ مِنْ تَصَرُّفِهِ. أَشَارَتْ إِلَيْهِ حُورُ بِلُطْفٍ فَقَامَ وَجَلَسَ بِقُرْبِهَا فِي طَرَفِ المَجْلِسِ يُقَدِّمُ التَّمْرَ وَالمَاءَ لِلضُّيُوفِ، وَهَمَسَتْ لَهُ: «الجُلُوسُ فِي صَدْرِ المَجْلِسِ بِغَيْرِ حَقٍّ مِنْ عَلَامَاتِ الحُمْقِ، أَمَّا الكِيَاسَةُ وَالفِطْنَةُ فَهِيَ أَنْ يَعْرِفَ الإِنْسَانُ قَدْرَ نَفْسِهِ وَيَجْتَهِدَ فِي البِرِّ وَالأَدَبِ، مُسْتَعْمِلاً مَرْكَزَ القَرَارِ الصَّادِقِ فِي نَاصِيَةِ دِمَاغِهِ لِيَخْتَارَ السُّلُوكَ الأَجْمَلَ دَائِماً».",
