          "content": "نَخْتَتِمُ الدَّوْرَةَ الأُولَى مِنْ سَنَتِكَ الثَّالِثَةِ بِتَأَمُّلِ وَحْدَةِ النِّظَامِ الكَوْنِيِّ الفَسِيحِ: فَمِنْ أَصْغَرِ خَلِيَّةٍ حَيَّةٍ وَذَرَّةٍ دَقِيقَةٍ تَدُورُ أَجْزَاؤُهَا بِنِظَامٍ مَحْسُوبٍ، إِلَى الكَوَاكِبِ وَالمَجَرَّاتِ السَّابِحَةِ فِي الفَضَاءِ، يَسْرِي قَانُونٌ هَنْدَسِيٌّ وَاحِدٌ يَشْهَدُ بِعِلْمِ الخَالِقِ وَقُدْرَتِهِ البَالِغَةِ، كَمَا صَوَّرَهُ الإِمَامُ عَلِيٌّ عَلَيْهِ السَّلَامُ فِي بَيَانِهِ البَدِيعِ:\n\n«وَنَظَمَ نُجُومَهَا عَلَى مَدَارِجِ أَفْلَاكِهَا... وَجَرَتْ عَلَى أَذْلَالِ تَسْخِيرِهَا مِنْ دَيْمُومَةِ سُلْطَانِهِ».\n\nانْظُرْ كَيْفَ وُصِفَتِ النُّجُومُ وَهِيَ مُنْتَظِمَةٌ كَاللَّآلِئِ فِي مَدَارَاتِهَا تَجْرِي طَائِعَةً لِقَانُونِ خَالِقِهَا! وَفِي مَرْسَمِ الخِتَامِ لِهَذِهِ الدَّوْرَةِ، تَجْمَعُ حَصِيلَةَ مَهَارَاتِكَ الجَدِيدَةِ (التَّنَاسُبَ الهَنْدَسِيَّ، الزَّهْرَةَ السُّدَاسِيَّةَ، التَّظْلِيلَ الأُسْطُوَانِيَّ، وَالمَنْظُورَ) فِي لَوْحَةِ التَّكْوِينِ الكَوْنِيِّ وَالعُمْرَانِيِّ.\n\n▪ اكْتُبْ أَسْفَلَ لَوْحَتِكَ سَطْراً مُتَكَامِلاً بِخَطِّ النَّسْخِ المَوْزُونِ بِالنِّقَاطِ: «إِنَّ العَقْلَ نُورٌ، وَالعِلْمَ فَرِيضَةٌ، وَالعَدْلَ مِيزَانُ العُمْرَانِ».\n\n▪ التَّطْبِيقُ العَمَلِيُّ: ارْسُمْ مَرْصَداً عِلْمِيّاً بِعَمُودَيْنِ مُظَلَّلَيْنِ بِالأُسْطُوَانَةِ وَمَمَرٍّ مَرْسُومٍ بِالمَنْظُورِ يَتَّجِهُ نَحْوَ قُبَّةٍ تَعْلُوهَا سَمَاءٌ مُزْدَانَةٌ بِمَدَارَاتِ النُّجُومِ المُنْتَظِمَةِ.",
